    item('cpr-aed', 'While the AED analyzes rhythm, rescuers should:', 'Ensure no one is touching the patient', ['Continue compressions through analysis', 'Pour water on the chest', 'Remove oxygen tubing only'], 'Motion and contact can interfere with rhythm analysis.', ['AHA_BLS'], 'intermediate'),
